import numpy as np
from scipy.optimize import minimize

def E_func_5(vars):
    x1, x2, x3 = vars
    x4 = 1.0 / (x1 * x2 * x3)
    cond = 1 + x3*x4 + x2*x3 + x2*x3**2*x4 - x3 - x2*x3*x4
    return x1 + x2 + x3 + x4, cond

def objective(vars):
    return E_func_5(vars)[0]

def constraint(vars):
    return E_func_5(vars)[1]

cons = {'type': 'eq', 'fun': constraint}
for start in [[1, 1, 1], [0.1, 0.1, 0.1], [10, 10, 10], [0.5, 2, 0.5], [2, 0.5, 2]]:
    res = minimize(objective, start, constraints=cons, bounds=[(1e-6, None), (1e-6, None), (1e-6, None)])
    print(f"Start {start}: {res.fun}")

