import numpy as np
from scipy.optimize import minimize

def objective(vars):
    p, q, r, s = vars
    return p/q + r/p + s/r + q/s

def constraint(vars):
    p, q, r, s = vars
    return (p + s) * (r + q) - (p * s + q * r)

cons = {'type': 'eq', 'fun': constraint}
for start in [[0.1, 1, 1, 0.1], [1, 0.1, 0.1, 1], [2, 1, 1, 2], [0.5, 2, 2, 0.5]]:
    res = minimize(objective, start, constraints=cons, bounds=[(1e-6, None), (1e-6, None), (1e-6, None), (1e-6, None)])
    print(f"Start {start}: Fun={res.fun}, Constraint={res.fun if False else constraint(res.x)}")
